def is_simple_power(x: Union[float, int], n: Union[float, int]) -> bool:
    ''' Check if x is a simple power of n, i.e., exists integer k such that n^k = x '''
    # Handle edge cases
    if x == 0:
        return n == 0
    if n == 0:
        return x == 0
    if x == 1:
        return True  # n^0 = 1 for any n != 0
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1 or x == -1

    # Check sign compatibility
    if (x < 0) != (n < 0):
        # Different signs
        if n > 0:
            # n is positive, x is negative: impossible
            return False
        # else, n is negative and x is positive. Exponent must be even.

    abs_x = abs(x)
    abs_n = abs(n)

    try:
        log_val = math.log(abs_x, abs_n)
    except ValueError:
        # This can happen if abs_n is 1, but we already handled n == 1 and n == -1
        return False

    tolerance = 1e-10
    k = round(log_val)
    # Check k-1, k, k+1 to handle floating point inaccuracies
    for candidate_k in (k-1, k, k+1):
        try:
            power = abs_n ** candidate_k
        except OverflowError:
            # If the power is too large or too small, skip
