                # Check parity of candidate_k
                if candidate_k % 2 == 0:
                    # even exponent: result is positive
                    return x > 0
                else:
                    # odd exponent: result is negative
                    return x < 0
            else:
                # n is positive, result is positive
                return x > 0
    return False

